  1	import { readFile } from 'fs/promises';
  2	import { join } from 'path';
  3	import {
  4	  RepositoryRegistrySchema,
  5	  type RepositoryEntry,
  6	  type RepositoryRegistry,
  7	} from '../schema/repository-registry.js';
  8	import { atomicWriteJson } from './atomic-writer.js';
  9	import { withLock } from './file-lock.js';
 10	
 11	/**
 12	 * File name for the central repository registry.
 13	 * Stored directly under the ledger root — not inside any project sub-directory.
 14	 */
 15	const REGISTRY_FILENAME = '.repositories.json';
 16	
 17	/**
 18	 * Returns the absolute path of the registry file for a given ledger root.
 19	 *
 20	 * @param ledgerRoot - Absolute path to the centralized ledger root directory
 21	 */
 22	function registryPath(ledgerRoot: string): string {
 23	  return join(ledgerRoot, REGISTRY_FILENAME);
 24	}
 25	
 26	// ==================== Public API ====================
 27	
 28	/**
 29	 * Reads and parses the `.repositories.json` registry file.
 30	 *
 31	 * Returns `{ repositories: [] }` when:
 32	 *   - the file does not exist (first-run scenario)
 33	 *   - the file exists but contains malformed JSON or fails schema validation
 34	 *
 35	 * Callers that need to distinguish between "absent" and "corrupt" should
 36	 * handle errors from `atomicWriteJson` / `saveRegistry` separately.
 37	 *
 38	 * @param ledgerRoot - Absolute path to the centralized ledger root directory
 39	 */
 40	export async function loadRegistry(
 41	  ledgerRoot: string
 42	): Promise<RepositoryRegistry> {
 43	  const path = registryPath(ledgerRoot);
 44	
 45	  try {
 46	    const content = await readFile(path, 'utf-8');
 47	    const data = JSON.parse(content);
 48	    return RepositoryRegistrySchema.parse(data);
 49	  } catch {
 50	    // Missing file, malformed JSON, or schema validation failure — return empty registry
 51	    return { repositories: [] };
 52	  }
 53	}
 54	
 55	/**
 56	 * Writes the registry to `.repositories.json` atomically under a file lock.
 57	 *
 58	 * The lock is acquired on `ledgerRoot` so that concurrent writes to any
 59	 * ledger file within the same root are serialized by the same lock.
 60	 * The write itself uses `atomicWriteJson` (write-to-temp-then-rename) so
 61	 * readers never observe a partial write.
 62	 *
 63	 * @param ledgerRoot - Absolute path to the centralized ledger root directory
 64	 * @param registry   - Registry data to persist (validated against schema before write)
 65	 * @throws Error if schema validation fails or if the atomic write fails
 66	 */
 67	export async function saveRegistry(
 68	  ledgerRoot: string,
 69	  registry: RepositoryRegistry
 70	): Promise<void> {
 71	  const validated = RepositoryRegistrySchema.parse(registry);
 72	  const path = registryPath(ledgerRoot);
 73	
 74	  await withLock(ledgerRoot, async () => {
 75	    await atomicWriteJson(path, validated);
 76	  });
 77	}
 78	
 79	/**
 80	 * Finds the first registry entry whose `folder_names` array contains the
 81	 * given folder name (case-sensitive exact match).
 82	 *
 83	 * This is a pure, synchronous lookup that does not perform any I/O.
 84	 * Call `loadRegistry()` to obtain a registry before passing it here.
 85	 *
 86	 * @param registry   - The in-memory registry to search
 87	 * @param folderName - Workspace folder name to search for
 88	 * @returns The matching `RepositoryEntry`, or `null` if no entry matches
 89	 */
 90	export function findByFolderName(
 91	  registry: RepositoryRegistry,
 92	  folderName: string
 93	): RepositoryEntry | null {
 94	  for (const entry of registry.repositories) {
 95	    if (entry.folder_names.includes(folderName)) {
 96	      return entry;
 97	    }
 98	  }
 99	  return null;
100	}

