11	import type { RepositoryRegistry, RepositoryEntry } from '../../src/schema/repository-registry.js';
12	
13	// ─── Fixtures ──────────────────────────────────────────────────────────────
14	
15	function makeEntry(overrides: Partial<RepositoryEntry> = {}): RepositoryEntry {
16	  return {
17	    id: 'my-repo',
18	    label: 'My Repository',
19	    folder_names: ['my-repo'],
20	    vision: {
21	      short_term: null,
22	      mid_term: null,
23	      long_term: null,
24	    },
25	    created_at: '2026-06-01T00:00:00Z',
26	    last_modified: '2026-06-01T00:00:00Z',
27	    ...overrides,
28	  };
29	}
