40	describe('repository-registry storage module', () => {
41	  let tempLedgerRoot: string;
42	
43	  beforeEach(async () => {
44	    tempLedgerRoot = await mkdtemp(join(tmpdir(), 'repo-registry-test-'));
45	  });
46	
