51	  // ─── loadRegistry ──────────────────────────────────────────────────────
52	
53	  describe('loadRegistry', () => {
54	    it('returns { repositories: [] } when .repositories.json does not exist', async () => {
55	      const result = await loadRegistry(tempLedgerRoot);
56	      expect(result).toEqual({ repositories: [] });
57	    });
58	
59	    it('does not throw when the file does not exist', async () => {
60	      await expect(loadRegistry(tempLedgerRoot)).resolves.not.toThrow();
61	    });
62	
63	    it('correctly parses a valid .repositories.json file and returns typed RepositoryRegistry', async () => {
64	      const entry = makeEntry({
65	        id: 'acme-web',
66	        label: 'Acme Web App',
67	        folder_names: ['acme-web', 'acme'],
68	        vision: {
69	          short_term: 'Ship MVP',
70	          mid_term: 'Expand feature set',
71	          long_term: null,
72	        },
73	      });
74	      const registry: RepositoryRegistry = { repositories: [entry] };
75	      await writeFile(
